import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip processing for non-POST requests to avoid unnecessary work
  if (req.method !== "POST") {
    return next();
  }

  // Check if the request path includes '/bank-link'
  if (!req.path.includes("/bank-link")) {
    return next();
  }

  const token = req.body?.token;

  if (!token) {
    return next(new Error("Token is required"));
  }

  if (!process.env.JWT_SECRET) {
    return next(new Error("JWT_SECRET is not set"));
  }

  try {
    const crypto = require("node:crypto");
    const hmac = crypto.createHmac("sha256", process.env.JWT_SECRET);
    hmac.update(token);
    const expectedSignature = hmac.digest("hex");

    const providedSignature = req.headers["x-signature"] as string | undefined;

    if (!providedSignature || !crypto.timingSafeEqual(Buffer.from(providedSignature), Buffer.from(expectedSignature))) {
      return next(new Error("Invalid token signature"));
    }
  } catch (error) {
    return next(error);
  }

  next();
}

