import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(401).send('JWT secret is not set');
    return;
  }

  if (req.method === 'GET' && req.path.startsWith('/applicants')) {
    // Extract the company ID from the path
    const companyId = req.path.split('/')[2];
    if (!companyId) {
      res.status(400).send('Company ID is missing');
      return;
    }

    // Verify the token
    const authHeader = req.headers['authorization'];
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.status(401).send('Authorization header is missing or invalid');
      return;
    }

    const token = authHeader.substring(7);
    try {
      const decoded = Buffer.from(token, 'base64').toString('utf8');
      const [header, payload] = decoded.split('.');
      const hmac = require('crypto').createHmac('sha256', jwtSecret);
      hmac.update(header + '.' + payload);
      const digest = hmac.digest('base64');

      if (require('crypto').timingSafeEqual(Buffer.from(digest, 'base64'), Buffer.from(token.split('.')[2]))) {
        // Token is valid, proceed with the request
        next();
      } else {
        res.status(403).send('Invalid token');
      }
    } catch (error) {
      res.status(403).send('Invalid token');
    }
  } else {
    // Allow other requests to pass through
    next();
  }
}

