const router = Router();

// Function to run scheduled automation rules
async function runScheduledRules() {
  const schedules = await getSchedules();
  for (const schedule of schedules) {
    const now = new Date().toISOString();
    if (schedule.trigger_time <= now) {
      const device = await getDeviceById(schedule.device_id);
      if (device) {
        switch (schedule.action) {
          case "turnOn":
            updateDeviceState(device.id, "on");
            break;
          case "turnOff":
            updateDeviceState(device.id, "off");
            break;
          default:
            console.log(`Unknown action: ${schedule.action}`);
        }
      }
      // Delete the executed schedule
      deleteSchedule(schedule.id);
    }
  }
