import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-manager scoped approval requests
  if (req.method !== "POST" || !req.path.startsWith("/api/expenses/approve")) {
    return next();
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    return res.status(401).send("JWT secret is not set");
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).send("No authorization header provided");
  }

  const token = authHeader.split(" ")[1];
  try {
    const decoded = require("jsonwebtoken").verify(token, jwtSecret);
    const userId = decoded.userId;

    // Assuming there's a function to get direct reports of a user
    const directReports = getDirectReports(userId);

    if (!directReports.includes(req.body.reportId)) {
      return res.status(403).send("Unauthorized access");
    }

    next();
  } catch (err) {
    return res.status(401).send("Invalid token");
  }
}

